//! Actual pinned-Go WHIP HTTP envelope comparison. The rows are captured from the
//! fixed Go server (`pkg/service/whipservice.go` at v1.13.10, e5655ac2) and read back
//! here; nothing is generated by this crate, so a Rust-side change cannot quietly
//! redefine the contract. Requests run through the full middleware chain
//! ([`crate::http::router`]), so the grant a row describes reaches the handler the same
//! way `APIKeyAuthMiddleware` delivers it upstream.
use super::*;
use axum::body::Body;
use rtc_core::permission::{Grants, VideoGrant};
use serde_json::json;
use tower::ServiceExt;

/// One captured Go response for one stimulus.
#[derive(serde::Deserialize)]
struct Row {
    id: String,
    method: String,
    path: String,
    #[serde(default)]
    content_type: Option<String>,
    #[serde(default)]
    if_match: Option<String>,
    /// The token's identity claim, or empty for a token with no subject.
    #[serde(default)]
    identity: String,
    /// The token's `video` claim object, or null to present no token at all.
    #[serde(default)]
    video: Option<serde_json::Value>,
    /// Non-empty when the row's request carries an SDP offer or ICE fragment body.
    #[serde(default)]
    body: Option<String>,
    status: u16,
    #[serde(default)]
    response_content_type: Option<String>,
    #[serde(default)]
    error: Option<String>,
    #[serde(default)]
    empty_body: bool,
}

const ROW_KEY_ID: &str = "devkey";
const ROW_KEY_SECRET: &str = "secret";

/// The wire shape of `auth.VideoGrant` (protocol/auth/grants.go), spelled here in
/// its camelCase JSON form so a row can be transcribed from the Go source without
/// re-deriving field semantics.
fn video_grant(video: &serde_json::Value) -> VideoGrant {
    let field_bool = |name: &str| video.get(name).and_then(|v| v.as_bool()).unwrap_or(false);
    let field_str = |name: &str| {
        video
            .get(name)
            .and_then(|v| v.as_str())
            .unwrap_or_default()
            .to_owned()
    };
    VideoGrant {
        room_create: field_bool("roomCreate"),
        room_list: field_bool("roomList"),
        room_record: field_bool("roomRecord"),
        room_admin: field_bool("roomAdmin"),
        room_join: field_bool("roomJoin"),
        room: field_str("room"),
        destination_room: field_str("destinationRoom"),
        can_publish: video.get("canPublish").and_then(|v| v.as_bool()),
        can_subscribe: video.get("canSubscribe").and_then(|v| v.as_bool()),
        can_publish_data: video.get("canPublishData").and_then(|v| v.as_bool()),
        can_publish_sources: video
            .get("canPublishSources")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .map(|s| s.as_str().unwrap_or_default().to_owned())
                    .collect()
            })
            .unwrap_or_default(),
        can_update_own_metadata: video.get("canUpdateOwnMetadata").and_then(|v| v.as_bool()),
        ingress_admin: field_bool("ingressAdmin"),
        hidden: field_bool("hidden"),
        recorder: field_bool("recorder"),
        agent: field_bool("agent"),
        can_subscribe_metrics: video.get("canSubscribeMetrics").and_then(|v| v.as_bool()),
        can_manage_agent_session: video.get("canManageAgentSession").and_then(|v| v.as_bool()),
    }
}

/// Mint the row's token with the project minter, so the claims that reach the verifier
/// are the same bytes an official client would send.
fn token_for(row: &Row) -> String {
    let keys = Arc::new(crate::auth::KeyStore::new(vec![(
        ROW_KEY_ID.into(),
        ROW_KEY_SECRET.into(),
    )]));
    let minter = crate::auth::TokenMinter::new(keys);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    minter
        .mint(
            ROW_KEY_ID,
            &crate::auth::TokenClaims {
                identity: row.identity.clone(),
                // An empty `video` object still means "the video claim was
                // present": whipservice.go:122 distinguishes nil from non-nil.
                video: Some(video_grant(row.video.as_ref().unwrap())),
                ..Default::default()
            },
            Duration::from_secs(600),
            now,
        )
        .expect("row token mints")
}

async fn send(state: &AppState, row: &Row) -> Response {
    let mut uri = row.path.clone();
    if row.video.is_some() {
        // Percent-encode nothing: a JWT is already URL-safe base64.
        uri.push_str(&format!("?access_token={}", token_for(row)));
    }
    let mut builder = axum::http::Request::builder()
        .method(row.method.as_str())
        .uri(uri);
    if let Some(ct) = &row.content_type {
        builder = builder.header("content-type", ct.as_str());
    }
    if let Some(tag) = &row.if_match {
        builder = builder.header("if-match", tag.as_str());
    }
    crate::http::router(state.clone())
        .oneshot(
            builder
                .body(Body::from(row.body.clone().unwrap_or_default()))
                .unwrap(),
        )
        .await
        .unwrap()
}

/// Every pinned-Go row's status, Content-Type and JSON error envelope, driven through
/// the real chain. Rows whose body is not an error envelope (the 201 SDP answer, the
/// 200 ICE-restart fragment) need live media and are out of scope here.
#[test]
#[ignore = "requires coordinator-run actual pinned-Go WHIP HTTP envelope rows"]
fn whip_http_envelope_rows_match_pinned_go() {
    let text = std::fs::read_to_string(
        std::env::var("WHIP_HTTP_GO_ROWS").expect("actual pinned-Go rows path"),
    )
    .unwrap();
    let rows: Vec<Row> = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    assert!(!rows.is_empty(), "pinned-Go rows must be provided");
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    rt.block_on(async {
        let (state, net) = crate::test_support::state_with_keys(vec![(
            ROW_KEY_ID.to_string(),
            ROW_KEY_SECRET.to_string(),
        )])
        .await;
        for row in &rows {
            let response = send(&state, row).await;
            assert_eq!(
                u16::from(response.status()),
                row.status,
                "{} status",
                row.id
            );
            let content_type = response
                .headers()
                .get(header::CONTENT_TYPE)
                .map(|v| v.to_str().unwrap().to_owned());
            assert_eq!(
                content_type.as_deref(),
                row.response_content_type.as_deref(),
                "{} content-type",
                row.id
            );
            let body = axum::body::to_bytes(response.into_body(), 1 << 20)
                .await
                .unwrap();
            if row.empty_body {
                assert!(body.is_empty(), "{} body must be empty", row.id);
                continue;
            }
            // Go's json.Encoder writes the envelope with a trailing newline.
            assert_eq!(
                String::from_utf8_lossy(&body),
                format!(
                    "{{\"error\":{}}}\n",
                    go_json_quote(row.error.as_deref().unwrap_or_default())
                ),
                "{} body",
                row.id
            );
        }
        state.manager.close_all().await;
        state.agents.shutdown().await;
        state.shutdown_whip().await;
        net.shutdown();
    });
}

/// Go `encoding/json` escapes `<`, `>` and `&`; the handler under test reproduces that,
/// so the reference quoting is written independently here.
fn go_json_quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '<' => out.push_str("\\u003c"),
            '>' => out.push_str("\\u003e"),
            '&' => out.push_str("\\u0026"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Silence an unused-import warning when the rows are absent: `Grants` documents the
/// shape the handlers read out of the verified token.
#[allow(dead_code)]
fn _grants_shape(grants: &Grants) -> &VideoGrant {
    &grants.video
}

/// The same rows as a committed inline table, so every WHIP HTTP leaf has an always-on
/// differential check against pinned-Go-captured values. The `#[ignore]`d test above
/// re-reads the coordinator-owned external capture; this table is the versioned copy
/// of those measured responses (captured 2026-11-25 against livekit v1.13.10 @
/// e5655ac2, single-node routing, `keys: devkey: secret`, listening on
/// 127.0.0.1:18787; each row cites the Go line that produced it).
///
/// Deliberately NOT in this table, because the local capture could not observe them:
/// - PATCH/DELETE on an unknown participant: the psrpc participant topic only
///   exists while a room hosts that identity, so both calls timed out after the
///   3 s RPC deadline and Go answered 500 (restart/trickle) and 404 (delete) with
///   `{"error":"no response from servers"}` (whipservice.go:354-356, 517-520). The
///   Rust local sessions reproduce the same message (mod.rs failure_message), and
///   the existing mod.rs tests pin it; the true `participant does not exist` 404
///   mapping needs a Redis multi-node capture where the topic exists but the
///   participant does not.
/// - The POST 201 success envelope (Location/ETag/Link headers, SDP answer): needs
///   real ICE/DTLS media on both sides; covered by the main_server_consumer tests.
#[tokio::test]
async fn whip_http_envelope_table_matches_pinned_go() {
    let join = || json!({"roomJoin": true, "room": "whip-row-room"});
    // (id, method, path, req content-type, If-Match, identity, video, body,
    //  status, resp content-type, error, empty body)
    type RawRow = (
        &'static str,
        &'static str,
        &'static str,
        Option<&'static str>,
        Option<&'static str>,
        &'static str,
        Option<serde_json::Value>,
        Option<&'static str>,
        u16,
        Option<&'static str>,
        Option<&'static str>,
        bool,
    );
    let rows: Vec<RawRow> = vec![
        // GET /whip/v1 — whipservice.go:88-91: bare 204, no headers set.
        (
            "get-root", "GET", "/whip/v1", None, None, "", None, None, 204, None, None, true,
        ),
        // OPTIONS /whip/v1 — whipservice.go:93-100: 200 plus exactly four CORS
        // headers; the measured dump shows no Content-Type on the reply.
        (
            "options-root",
            "OPTIONS",
            "/whip/v1",
            None,
            None,
            "",
            None,
            None,
            200,
            None,
            None,
            true,
        ),
        // POST without any token — grants are nil, validateCreate hits
        // whipservice.go:122-125 with rtc.ErrPermissionDenied (pkg/rtc/errors.go:24
        // "no permissions to access the room"). Measured 401, Content-Type
        // application/sdp (added at whipservice.go:216 before validation).
        (
            "post-no-auth",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "",
            None,
            None,
            401,
            Some("application/sdp"),
            Some("no permissions to access the room"),
            false,
        ),
        // POST with a video grant lacking roomJoin — EnsureJoinPermission returns
        // service.ErrPermissionDenied (auth.go:46,172-185 "permissions denied"),
        // whipservice.go:127-130. Measured 401.
        (
            "post-no-join",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "w-row-a",
            Some(json!({"room": "whip-row-room"})),
            None,
            401,
            Some("application/sdp"),
            Some("permissions denied"),
            false,
        ),
        // POST with roomJoin but an empty room — whipservice.go:131-133. Measured 401.
        (
            "post-empty-room",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "w-row-a",
            Some(json!({"roomJoin": true})),
            None,
            401,
            Some("application/sdp"),
            Some("room name cannot be empty"),
            false,
        ),
        // POST with a valid join grant but no identity claim — whipservice.go:138-140,
        // service.ErrIdentityEmpty (errors.go:24). Measured 400.
        (
            "post-empty-identity",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "",
            Some(join()),
            None,
            400,
            Some("application/sdp"),
            Some("identity cannot be empty"),
            false,
        ),
        // POST with a wrong content-type — checked first (whipservice.go:211-213)
        // before the sdp Content-type is added, so Go sniffs text/plain. Measured 400.
        (
            "post-wrong-ct",
            "POST",
            "/whip/v1",
            Some("application/json"),
            None,
            "w-row-a",
            Some(join()),
            None,
            400,
            Some("text/plain; charset=utf-8"),
            Some("unsupported content-type: application/json"),
            false,
        ),
        // POST with a correct content-type and a true zero-byte body — io.ReadAll
        // succeeds with 0 bytes, whipservice.go:166-168. Measured 400.
        (
            "post-empty-body",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "w-row-a",
            Some(join()),
            Some(""),
            400,
            Some("application/sdp"),
            Some("body does not have SDP offer"),
            false,
        ),
        // POST with a syntactically invalid SDP offer — Pion Unmarshal fails,
        // whipservice.go:174-177. Message measured verbatim from pion/webrtc v4.
        (
            "post-malformed-sdp",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "w-row-a",
            Some(join()),
            Some("not an sdp at all\r\n"),
            400,
            Some("application/sdp"),
            Some("malformed SDP offer: failed to unmarshal SDP: sdp: syntax error at pos 1: \"o\""),
            false,
        ),
        // POST with an over-long room name — whipservice.go:134-136,
        // ErrRoomNameExceedsLimits (errors.go:33) formatted with the limit.
        // Measured 400 `room name length exceeds limits: max length 256`.
        (
            "post-long-room",
            "POST",
            "/whip/v1",
            Some("application/sdp"),
            None,
            "w-row-a",
            Some(json!({"roomJoin": true, "room": "r".repeat(257)})),
            None,
            400,
            Some("application/sdp"),
            Some("room name length exceeds limits: max length 256"),
            false,
        ),
        // GET /whip/v1/{id} — whipservice.go:312-315: bare 204, no auth needed.
        (
            "get-resource",
            "GET",
            "/whip/v1/PA_row",
            None,
            None,
            "",
            None,
            None,
            204,
            None,
            None,
            true,
        ),
        // PATCH with a wrong content-type — whipservice.go:429-431, before the
        // sdpfrag Content-type is added at :434, so text/plain. Measured 400.
        (
            "patch-wrong-ct",
            "PATCH",
            "/whip/v1/PA_row",
            Some("application/json"),
            None,
            "w-row-a",
            Some(join()),
            None,
            400,
            Some("text/plain; charset=utf-8"),
            Some("unsupported content-type: application/json"),
            false,
        ),
        // PATCH without If-Match — whipservice.go:437-440. Measured 428 WITH the
        // sdpfrag Content-Type, because :434 runs first. Rust patch() follows the
        // same order: policy_error gets Some(CONTENT) here.
        (
            "patch-missing-tag",
            "PATCH",
            "/whip/v1/PA_row",
            Some("application/trickle-ice-sdpfrag"),
            None,
            "w-row-a",
            Some(join()),
            None,
            428,
            Some("application/trickle-ice-sdpfrag"),
            Some("missing entity tag"),
            false,
        ),
        // PATCH with If-Match but no token — whipservice.go:443-447. Measured 401.
        (
            "patch-no-auth",
            "PATCH",
            "/whip/v1/PA_row",
            Some("application/trickle-ice-sdpfrag"),
            Some("*"),
            "",
            None,
            None,
            401,
            Some("application/trickle-ice-sdpfrag"),
            Some("no permissions to access the room"),
            false,
        ),
        // PATCH with a valid join token but empty identity — whipservice.go:458-461.
        // Measured 401.
        (
            "patch-empty-identity",
            "PATCH",
            "/whip/v1/PA_row",
            Some("application/trickle-ice-sdpfrag"),
            Some("*"),
            "",
            Some(join()),
            None,
            401,
            Some("application/trickle-ice-sdpfrag"),
            Some("participant identity cannot be empty"),
            false,
        ),
        // DELETE without a token — whipservice.go:488-492. Measured 401 text/plain
        // (Delete never adds an SDP Content-type).
        (
            "delete-no-auth",
            "DELETE",
            "/whip/v1/PA_row",
            None,
            None,
            "",
            None,
            None,
            401,
            Some("text/plain; charset=utf-8"),
            Some("no permissions to access the room"),
            false,
        ),
    ];

    let (state, net) = crate::test_support::state().await;
    for r in rows {
        let (id, method, path, ct, if_match, identity, video, body, status, resp_ct, err, empty) =
            r;
        let row = Row {
            id: id.to_owned(),
            method: method.to_owned(),
            path: path.to_owned(),
            content_type: ct.map(str::to_owned),
            if_match: if_match.map(str::to_owned),
            identity: identity.to_owned(),
            video,
            body: body.map(str::to_owned),
            status,
            response_content_type: resp_ct.map(str::to_owned),
            error: err.map(str::to_owned),
            empty_body: empty,
        };
        let response = send(&state, &row).await;
        assert_eq!(
            u16::from(response.status()),
            row.status,
            "{} status",
            row.id
        );
        let got_ct = response
            .headers()
            .get(header::CONTENT_TYPE)
            .map(|v| v.to_str().unwrap().to_owned());
        assert_eq!(
            got_ct.as_deref(),
            row.response_content_type.as_deref(),
            "{} content-type",
            row.id
        );
        let bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
            .await
            .unwrap();
        if row.empty_body {
            assert!(bytes.is_empty(), "{} body must be empty", row.id);
            continue;
        }
        assert_eq!(
            String::from_utf8_lossy(&bytes),
            format!(
                "{{\"error\":{}}}\n",
                go_json_quote(row.error.as_deref().unwrap_or_default())
            ),
            "{} body",
            row.id
        );
    }
    state.manager.close_all().await;
    state.agents.shutdown().await;
    state.shutdown_whip().await;
    net.shutdown();
}

/// The POST allocation-failure row, kept separate because it needs the node record
/// rewound past the literal 5 s liveness window (`selector.IsAvailable`, protocol
/// routing/selector/utils.go:30-41). With the local node stale, Go's
/// StandardRoomAllocator.SelectRoomNode falls through to AnySelector.SelectNode
/// (roomallocator.go:158-163 → selector/any.go:29-34) and handleCreate reports 500
/// (whipservice.go:224-227). Captured 2026-11-25 against the pinned binary:
/// HTTP 500, Content-Type application/sdp, body
/// `{"error":"could not find any available nodes"}`.
#[tokio::test]
async fn whip_post_stale_node_allocation_failure_matches_pinned_go() {
    let row = Row {
        id: "post-stale-node".into(),
        method: "POST".into(),
        path: "/whip/v1".into(),
        content_type: Some("application/sdp".into()),
        if_match: None,
        identity: "w-row-a".into(),
        video: Some(json!({"roomJoin": true, "room": "whip-row-room"})),
        body: Some(
            "v=0\r\no=- 1 1 IN IP4 127.0.0.1\r\ns=-\r\nt=0 0\r\na=group:BUNDLE 0\r\n\
             m=audio 9 UDP/TLS/RTP/SAVPF 111\r\na=ice-ufrag:AAAA\r\na=ice-pwd:BBBBBBBBBBBBBBBBBBBBBBBB\r\n\
             a=fingerprint:sha-256 BA:DB:7E:F0:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00\r\n\
             a=setup:actpass\r\na=mid:0\r\na=sendonly\r\n"
                .into(),
        ),
        status: 500,
        response_content_type: Some("application/sdp".into()),
        error: Some("could not find any available nodes".into()),
        empty_body: false,
    };
    let (mut state, net) = crate::test_support::state().await;
    state.enable_node(Arc::new(
        crate::routing::LocalNode::serving(
            "ND_whip_row".into(),
            "127.0.0.1".into(),
            "".into(),
            1,
            rtc_core::util::unix_s(),
        )
        .expect("local node record"),
    ));
    state
        .enable_local_allocation_selector(crate::room_control::selector::Config {
            kind: "any".into(),
            sort_by: "".into(),
            algorithm: "".into(),
            cpu_limit: 0.9,
            sysload_limit: 0.9,
            region: "".into(),
            regions: vec![],
            track_limit: 0,
            bytes_limit: 0.0,
        })
        .expect("local allocation selector installs");
    // Rewind liveness beyond the 5 s IsAvailable window: the production keepalive
    // worker owns this clock, and only its staleness drives the selector fallback.
    state
        .node()
        .expect("node installed")
        .set_stale_for_test(rtc_core::util::unix_s() - 6);
    let response = send(&state, &row).await;
    assert_eq!(
        response.status(),
        StatusCode::INTERNAL_SERVER_ERROR,
        "status"
    );
    assert_eq!(
        response
            .headers()
            .get(header::CONTENT_TYPE)
            .map(|v| v.to_str().unwrap()),
        row.response_content_type.as_deref(),
        "content-type"
    );
    let bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
        .await
        .unwrap();
    assert_eq!(
        String::from_utf8_lossy(&bytes),
        format!(
            "{{\"error\":{}}}\n",
            go_json_quote(row.error.as_deref().unwrap_or_default())
        )
    );
    state.manager.close_all().await;
    state.agents.shutdown().await;
    state.shutdown_whip().await;
    net.shutdown();
}
